-- Charles, Oct 28. Shop, Regional and Franchisee Managers no longer approve tip payouts or see the
-- payout tracker by default: tips and payroll are the brand's, given only by an explicit grant.
-- Franchisee Owners keep them. The Apprentice template becomes Barber's access less checkout
-- discounts and refunds (Barber has neither). A shop's own copy of a role loses the same three.
UPDATE "roles" SET "permissions" = "permissions" - 'tips.approve' WHERE "key" IN ('shop_manager', 'regional_manager', 'franchisee_manager');--> statement-breakpoint
UPDATE "shop_sync_state" st SET "local" = jsonb_set(st."local", '{permissions}', (st."local"->'permissions') - 'tips.approve')
  FROM "roles" r WHERE st."key" = 'role:' || r."id"::text AND r."key" IN ('shop_manager', 'regional_manager', 'franchisee_manager')
  AND jsonb_typeof(st."local"->'permissions') = 'array';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" - 'payouts.view' WHERE "key" IN ('shop_manager', 'regional_manager', 'franchisee_manager');--> statement-breakpoint
UPDATE "shop_sync_state" st SET "local" = jsonb_set(st."local", '{permissions}', (st."local"->'permissions') - 'payouts.view')
  FROM "roles" r WHERE st."key" = 'role:' || r."id"::text AND r."key" IN ('shop_manager', 'regional_manager', 'franchisee_manager')
  AND jsonb_typeof(st."local"->'permissions') = 'array';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" - 'payouts.manage' WHERE "key" IN ('shop_manager', 'regional_manager', 'franchisee_manager');--> statement-breakpoint
UPDATE "shop_sync_state" st SET "local" = jsonb_set(st."local", '{permissions}', (st."local"->'permissions') - 'payouts.manage')
  FROM "roles" r WHERE st."key" = 'role:' || r."id"::text AND r."key" IN ('shop_manager', 'regional_manager', 'franchisee_manager')
  AND jsonb_typeof(st."local"->'permissions') = 'array';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["clients.rate"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'clients.rate';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["clients.message"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'clients.message';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["notes.write"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'notes.write';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["blocks.own"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'blocks.own';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["reports.money"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'reports.money';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["report.my_sales.export"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'report.my_sales.export';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["report.service_times.export"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'report.service_times.export';--> statement-breakpoint
UPDATE "roles" SET "permissions" = "permissions" || '["report.rebook_rate.view"]'::jsonb WHERE "key" = 'apprentice' AND NOT "permissions" ? 'report.rebook_rate.view';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages a franchisee''s locations day to day: front desk, POS, clients, staff and shop settings, with every report for those locations but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission) and tip payout approval, unless granted.' WHERE "key" = 'franchisee_manager' AND "description" = 'Manages a franchisee''s locations day to day: front desk, POS, clients, staff and shop settings, with every report for those locations but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages several shops: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with every report for those shops but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission) and tip payout approval, unless granted.' WHERE "key" = 'regional_manager' AND "description" = 'Manages several shops: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with every report for those shops but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Manages one shop: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with that shop''s reports but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission) and tip payout approval, unless granted.' WHERE "key" = 'shop_manager' AND "description" = 'Manages one shop: front desk, POS, clients, staff and shop settings, the Campaign Center''s We have openings, with that shop''s reports but the brand''s marketing and pay reports (each person''s tips, payroll, payouts and commission).';--> statement-breakpoint
UPDATE "roles" SET "description" = 'Learning the trade: everything a barber has (their own column, clients, notes, blocks, time clock, timesheet, tips and sales), with no checkout discounts, price changes or refunds. The brand can edit it like any role.' WHERE "key" = 'apprentice' AND "description" = 'Learning the trade: their own column and clients at menu prices, client notes to read, the time clock, their own timesheet and tips. No discounts, refunds or blocking time, and their own reports show counts and times but no dollar amounts.';
